-- -----------------------------------
-- Table structure for `dvrsite`
-- -----------------------------------

DROP TABLE IF EXISTS `dvrsite`;
CREATE TABLE `dvrsite` (
  `SN` int(3) NOT NULL AUTO_INCREMENT,
  `Status` varchar(22) CHARACTER SET utf8 DEFAULT NULL,
  `Phase` varchar(7) CHARACTER SET utf8 DEFAULT NULL,
  `Customer` varchar(50) CHARACTER SET utf8 DEFAULT NULL,
  `Bank` varchar(30) CHARACTER SET utf8 DEFAULT NULL,
  `ATMID` varchar(25) CHARACTER SET utf8 DEFAULT NULL,
  `ATMID_2` varchar(10) CHARACTER SET utf8 DEFAULT NULL,
  `ATMID_3` varchar(8) CHARACTER SET utf8 DEFAULT NULL,
  `ATMID_4` varchar(8) CHARACTER SET utf8 DEFAULT NULL,
  `TrackerNo` varchar(15) CHARACTER SET utf8 DEFAULT NULL,
  `ATMShortName` varchar(150) CHARACTER SET utf8 DEFAULT NULL,
  `SiteAddress` text CHARACTER SET utf8,
  `City` varchar(50) CHARACTER SET utf8 DEFAULT NULL,
  `State` varchar(25) CHARACTER SET utf8 DEFAULT NULL,
  `Zone` varchar(15) CHARACTER SET utf8 DEFAULT NULL,
  `DVRIP` varchar(20) CHARACTER SET utf8 DEFAULT NULL,
  `DVRName` varchar(20) CHARACTER SET utf8 DEFAULT NULL,
  `DVR_Model_num` varchar(250) CHARACTER SET utf8 NOT NULL,
  `DVR_Serial_num` varchar(100) CHARACTER SET utf8 NOT NULL,
  `CTSLocalBranch` varchar(200) CHARACTER SET utf8 NOT NULL,
  `CTS_BM_Name` varchar(100) CHARACTER SET utf8 NOT NULL,
  `CTS_BM_Number` varchar(100) CHARACTER SET utf8 NOT NULL,
  `HDD` varchar(100) CHARACTER SET utf8 NOT NULL,
  `Camera1` varchar(100) CHARACTER SET utf8 NOT NULL,
  `Camera2` varchar(100) CHARACTER SET utf8 NOT NULL,
  `Camera3` varchar(100) CHARACTER SET utf8 NOT NULL,
  `Attachment1` varchar(100) CHARACTER SET utf8 NOT NULL,
  `Attachment2` varchar(100) CHARACTER SET utf8 NOT NULL,
  `liveDate` datetime DEFAULT CURRENT_TIMESTAMP,
  `install_Status` varchar(100) CHARACTER SET utf8 NOT NULL,
  `UserName` varchar(5) CHARACTER SET utf8 DEFAULT NULL,
  `Password` varchar(15) CHARACTER SET utf8 DEFAULT NULL,
  `live` char(1) CHARACTER SET utf8 NOT NULL DEFAULT 'N',
  `current_dt` datetime DEFAULT NULL,
  `mailreceive_dt` datetime DEFAULT NULL,
  `addedby` varchar(50) CHARACTER SET utf8 DEFAULT NULL,
  `editby` varchar(50) CHARACTER SET utf8 DEFAULT NULL,
  `site_remark` varchar(1000) CHARACTER SET utf8 NOT NULL,
  `PanelIP` varchar(25) CHARACTER SET utf8 DEFAULT NULL,
  `last_modified` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `old_atmid` varchar(40) CHARACTER SET utf8 NOT NULL,
  `installationDate` datetime DEFAULT NULL,
  `project` varchar(20) CHARACTER SET utf8 NOT NULL DEFAULT 'DVR',
  `unique_id` varchar(50) CHARACTER SET utf8 NOT NULL,
  PRIMARY KEY (`SN`),
  KEY `live` (`live`),
  KEY `DVRIP` (`DVRIP`)
) ENGINE=MyISAM AUTO_INCREMENT=1319 DEFAULT CHARSET=latin1;

